idea.md:
`lo = 0`, `hi = n − 1`. While `lo < hi`: if `a[mid] > a[hi]`, the minimum is right of `mid` (`lo = mid + 1`);
otherwise it's at `mid` or left (`hi = mid`). Return `a[lo]`.

**Invariant.** The minimum's index is always in `lo … hi`.

code.python:
class Solution:
    def lowestReading(self, readings: List[int]) -> int:
        lo, hi = 0, len(readings) - 1
        while lo < hi:
            mid = (lo + hi) // 2
            if readings[mid] > readings[hi]:
                lo = mid + 1
            else:
                hi = mid
        return readings[lo]

code.java:
class Solution {
    public int lowestReading(int[] readings) {
        int lo = 0, hi = readings.length - 1;
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (readings[mid] > readings[hi]) lo = mid + 1;
            else hi = mid;
        }
        return readings[lo];
    }
}

